cand=[]
for r in range(6):
 for c in range(6):
  block={(r,c),(r,c+1),(r+1,c),(r+1,c+1)}
  if block<=S: cand.append((block,1,'square',(r,c)))
  for missing,col in [((r,c),2),((r+1,c),3),((r,c+1),4),((r+1,c+1),5)]:
   shape=block-{missing}
   if shape<=S: cand.append((shape,col,'L',(r,c)))
# exact cover recursively
sol=[]
def go(rem, pieces):
 if not rem:
  sol.append(pieces);return
 p=min(rem)
 for sh,col,typ,pos in cand:
  if p in sh and sh<=rem:
   go(rem-sh,pieces+[(sh,col,typ,pos)])
